\begin{theorem}[Myers]
\label{thm:myers}

\dcref{ch1:1.11}

If $M$ is a complete connected Riemannian manifold whose sectional curvature is bounded below by a
positive constant, then $M$ is compact and has finite fundamental group.
\end{theorem}

